package app.thawani

internal fun cards1(): List<Card> = listOf(
Card("p1","first_aid","الغصة والاختناق للبالغين والأطفال فوق سنة (مناورة هيمليخ)","997","طوارئ طبية حرجة — تدخل خلال ثوانٍ","c","إذا كان المصاب يسعل بقوة أو يستطيع الكلام: لا تضغط على بطنه أبداً، بل شجعه على السعال. تدخل فقط إذا عجز عن التنفس أو الصوت.",listOf("قف خلف المصاب مباشرة، ولفّ ذراعيك حول خصره، وأمِل جذعه قليلاً للأمام.","اصنع قبضة بإحدى يديك وضعها فوق السرة مباشرة بمسافة إصبعين (أسفل عظمة القص).","أمسك قبضتك باليد الأخرى، ووجه ضغطات سريعة وقوية للداخل وللأعلى (بحركة تشبه حرف J).","كرر الضغطات (5 مرات متتالية) حتى يخرج الجسم الغريب أو يعود التنفس الطبيعي.","في حال فقدان المصاب للوعي: أنزله برفق على الأرض، اتصل فوراً بـ 997، وابدأ الإنعاش القلبي الرئوي (CPR)."),listOf("لا تعطِ المصاب ماءً أو أي سوائل أثناء الغصة لأنها تزيد الانسداد.","لا تدخل أصابعك في فم المصاب بشكل عشوائي حتى لا تدفع الجسم الغريب للداخل.","لا تطبق الضغط على البطن للحوامل أو البدناء جداً (استخدم الضغطات الصدرية في منتصف الصدر)."),listOf("علامة الاختناق العالمية: إمساك المصاب لحلقه بكلتا يديه مع عدم القدرة على الكلام أو السعال.","إذا كنت وحدك وأصبت بغصة: اضغط ببطنك فوق حافة كرسي ثابت أو طاولة بقوة.","طلب الإسعاف (997) فوراً إذا استمر الانسداد أو تدهور الوعي."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر","المركبة والطريق"),listOf(Link("وزارة الصحة: الغصة","https://www.moh.gov.sa/awarenessplateform/FirstAid/Pages/Choking.aspx")),listOf(Link("إسعاف المصاب بالغصة أو الاختناق · الهلال الأحمر السعودي","https://youtu.be/dZ9-i_UpjlA"))),
Card("p2","first_aid","إيقاف النزيف الشرياني الحاد (التورنيكيه وحشو الجروح)","997","حرج جداً — إيقاف النزيف أولوية قصوى","d","الدم المفقود لا يعوض في الميدان؛ اضغط بقوة وثبات منذ الثانية الأولى ولا ترفع الشاش للتحقق من توقف الدم.",listOf("اكشف مكان الجرح بسرعة لتحديد مصدر النزيف الفعلي، واطلب الاتصال الفوري بـ 997.","للنزيف الحاد في الأطراف (الذراع أو الساق): ركّب التورنيكيه (العاصبة) أعلى الجرح بـ 5 إلى 7 سم (وليس فوق المفصل مباشرة).","شدّ ذراع التورنيكيه بقوة حتى يتوقف النزيف تماماً ويختفي النبض الطرفي، وثبّت الذراع في المشبك.","سجّل وقت تركيب التورنيكيه بدقة على شريط التورنيكيه أو جبين المصاب (شغّل المؤقت المدمج بالتطبيق).","للجروح العميقة في المناطق غير القابلة للتورنيكيه (كالرقبة أو الإبط أو الفخذ): احشُ الجرح بالشاش الطبي مع الضغط المباشر المستمر بكلتا اليدين لمدة 3 إلى 5 دقائق كاملة."),listOf("لا تقم بفك أو إرخاء التورنيكيه أبداً بعد تركيبه؛ فكه يتم بواسطة الفريق الطبي في المستشفى فقط.","لا تزل الشاش المشبع بالدم من الجرح، بل أضف طبقات جديدة فوقه مع استمرار الضغط.","لا تضع التورنيكيه فوق الركبة أو الكوع مباشرة أو فوق جيوب تحتوي على أجسام صلبة."),listOf("علامات النزيف الشرياني: خروج الدم بتدفق نبضي قوي أو بلون أحمر فاتح أو تجمع بركة دم سريعة.","تدفئة المصاب ببطانية لمنع الدخول في صدمة انخفاض الحرارة.","توثيق ساعة ودقيقة تركيب التورنيكيه وإبلاغ المسعفين بها فور وصولهم."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر","المركبة والطريق"),listOf(Link("الهلال الأحمر السعودي: التوعية الإسعافية","https://www.srca.gov.sa/first-aid-awareness/")),listOf(Link("إسعاف المصاب بالنزيف · الهلال الأحمر السعودي","https://youtu.be/f-icmfh97Es"))),
Card("p3","first_aid","الإنعاش القلبي الرئوي للبالغين (CPR)","997","حرج للغاية — كل ثانية تصنع فارقاً","c","اضغط بقوة وبسرعة في منتصف الصدر (100 إلى 120 ضغطة في الدقيقة) بعمق 5 إلى 6 سم، واسمح للصدر بالارتداد الكامل بعد كل ضغطة.",listOf("تأكد من أمان المكان، ثم هزّ كتفي المصاب، وارفع صوتك: (هل تسمعني؟) وتحقق من التنفس خلال 10 ثوانٍ فقط.","إذا لم يستجب ولا يتنفس طبيعياً: اطلب ممن حولك الاتصال بـ 997 فوراً وإحضار جهاز الصدمات الآلي (AED) إن وجد.","ضع المصاب على ظهره فوق سطح صلب، وضع كعب إحدى يديك في منتصف الصدر (على النصف السفلي لعظمة القص) وشبّك اليد الأخرى فوقها.","اجعل ذراعيك مستقيمتين واضغط بوزن جسمك عمودياً بمعدل 110 ضغطات في الدقيقة (يمكنك تشغيل النبض الصوتي في التطبيق لضبط الإيقاع).","استمر بالضغط المتواصل دون توقف حتى يعود التنفس أو يصل فريق الهلال الأحمر أو يتوفر جهاز الصدمات."),listOf("لا تتوقف عن الضغطات الصدرية لأكثر من 10 ثوانٍ تحت أي ظرف.","لا تثنِ المرفقين أثناء الضغط، ولا تضغط على الأضلاع الجانبية أو طرف عظمة القص السفلي.","لا تترك المصاب وحده للبحث عن مساعدة إذا كان معك هاتف يمكنك فتح مكبر الصوت فيه."),listOf("معدل الضغط القياسي: 100 إلى 120 ضغطة في الدقيقة (عمق 5 سم تقريباً).","تبديل المسعف كل دقيقتين (إن وجد شخص آخر) لمنع الإجهاد وضمان جودة الضغطات.","تشغيل مكبر الصوت في الجوال أثناء محادثة عمليات الهلال الأحمر (997) لتلقي التوجيهات."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر","المركبة والطريق"),listOf(Link("وزارة الصحة: التوعية بالإسعافات الأولية","https://www.moh.gov.sa/awarenessplateform/FirstAid/Pages/default.aspx")),listOf()),
Card("p4","first_aid","الحساسية المفرطة (الصدمة التحسسية - Anaphylaxis)","997","طوارئ طبية حرجة — خطر انسداد مجرى الهواء","c","إذا صاحبت الحساسية الجلدية صعوبة في التنفس أو بحّة في الصوت أو تورم في اللسان/الحلق أو دوخة شديدة، فهي صدمة تحسسية تتطلب قلم الإبينفرين (EpiPen) والإسعاف فوراً.",listOf("اتصل فوراً بالهلال الأحمر (997) وأبلغهم بوجود حالة اشتباه صدمة تحسسية حادة.","إذا كان لدى المصاب قلم الأدرينالين الذاتي (EpiPen): انزع غطاء الأمان الأزرق، واحقنه عمودياً في منتصف الفخذ الخارجي (يمكن الحقن من فوق الملابس) مع تثبيته لمدة 3 إلى 10 ثوانٍ.","اجعل المصاب يستلقي على ظهره مع رفع ساقيه للأعلى، أو في وضع الجلوس المريح إذا كان يعاني من ضيق تنفس شديد.","فكّ الملابس الضيقة حول الرقبة والصدر وراقب التنفس ومستوى الوعي باستمرار.","إذا لم تتحسن الأعراض، اتبع توجيه موظف الإسعاف بشأن جرعة ثانية إن توفر قلم آخر."),listOf("لا تكتفِ بمضادات الهيستامين الفموية في حالات تورم الحلق أو ضيق التنفس لأنها بطيئة المفعول.","لا تجعل المصاب يقف فجأة أثناء الصدمة التحسسية لأن ذلك قد يسبب هبوطاً حاداً وتوقفاً للقلب.","لا تحقن قلم الإبينفرين في الوريد أو الأصابع أو الأرداف؛ المكان الآمن الوحيد هو العضلة الخارجية للفخذ."),listOf("علامات التفريق الحاسمة: الحساسية العادية تقتصر على حكة/طفح، بينما الصدمة تشمل جهازين أو أكثر (تنفس، ضغط، بلع).","الاحتفاظ بالقلم المستعمل لتسليمه لطاقم الإسعاف وتحديد وقت الحقن."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: الحساسية المفرطة (التأق)","https://www.moh.gov.sa/healthawareness/educationalcontent/firstaid/pages/009.aspx")),listOf()),
Card("p5","first_aid","الاشتباه بالنوبة القلبية أو الجلطة الدماغية (قاعدة FAST)","997","حرج — عامل الوقت ينقذ الدماغ والقلب","d","في الجلطة الدماغية: احفظ وقت ظهور أول عرض بدقة بالدقيقة؛ فالعلاجات المذيبة للجلطة تعتمد كلياً على نافذة الوقت منذ بداية الأعراض.",listOf("للجلطة الدماغية طبّق فحص (FAST): اطلب منه الابتسام (هل الفم مائل؟)، رفع الذراعين (هل تسقط إحداهما؟)، نطق جملة بسيطة (هل الكلام متلعثم؟).","للنوبة القلبية: انتبه لألم أو ضغط عاصر في منتصف الصدر يمتد للذراع الأيسر أو الفك أو الظهر مع تعرق بارد وغثيان.","اتصل فوراً بـ 997 ولا تنتظر زوال الأعراض تلقائياً.","اجعل المصاب في وضع نصف جالس مريح (ظهره مسنود وركبتاه مثنيتان قليلاً) لتقليل العبء على القلب، وهدّئ من روعه.","لا تعطِ المصاب أي دواء (ومنه الأسبرين) إلا إذا وجّهك به موظف الطوارئ أو كان موصوفاً له، وابقَ معه حتى وصول الإسعاف."),listOf("لا تعطِ مصاب الجلطة الدماغية أي دواء (ومنه الأسبرين) أو طعام أو شراب، لأن الجلطة قد تكون نزفاً ولاحتمال شلل عضلات البلع.","لا تعطِ مصاب الجلطة الدماغية أي طعام أو شراب أو دواء عن طريق الفم لاحتمال شلل عضلات البلع.","لا تجعل المصاب يمشي أو يبذل أي مجهود بدني أو يقود سيارته بنفسه للمستشفى."),listOf("تدوين الدقيقة والساعة التي شوهد فيها المصاب طبيعياً لآخر مرة، وتجهيز قائمة أدويته المعتادة."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: التوعية بالإسعافات الأولية","https://www.moh.gov.sa/awarenessplateform/FirstAid/Pages/default.aspx"),Link("وزارة الصحة: التوعية بالسكتة الدماغية","https://www.moh.gov.sa/awarenessplateform/varioustopics/pages/stroke.aspx")),listOf()),
Card("p6","first_aid","الإسعاف الأولي للحروق الحرارية والكيميائية","997","تدخل إسعافي فوري لتقليل تلف الأنسجة","w","التبريد الفوري بماء الصنبور الجاري الفاتر (وليس المثلج) لمدة 15 إلى 20 دقيقة متواصلة هو أهم خطوة لإيقاف امتداد الحرق لطبقات الجلد العميقة.",listOf("أبعد المصاب فوراً عن مصدر الحرارة أو اللهب أو السائل الساخن.","ضع المنطقة المحروقة تحت ماء جارٍ معتدل البرودة لمدة 15 إلى 20 دقيقة متواصلة.","انزع الخواتم، الساعات، الأساور، والأحزمة برفق قبل أن تبدأ المنطقة بالتورم.","غطِّ الحرق بشكل غير ضاغط بشاش طبي معقم غير لاصق أو بغلاف بلاستيكي نظيف (نايلون تغليف الطعام) لحمايته من الهواء والعدوى.","اطلب الرعاية الطبية فوراً إذا كان الحرق في الوجه أو اليدين أو المفاصل أو كان أكبر من حجم كف يد المصاب."),listOf("لا تضع معجون الأسنان أو البن أو الدقيق أو الزبدة أو البيض أو الثلج المباشر على الحرق أبداً.","لا تقم بثقب أو فقء الفقاعات المائية المتكونة فوق الحرق لأنها تحمي الجلد التحتي من البكتيريا.","لا تنزع الملابس الملتصقة بالجلد المحروق بالقوة، بل قصّ القماش حولها واترك الجزء الملتصق للطبيب."),listOf("في الحروق الكيميائية (المنظفات القوية/الأسيد): اغسل بالماء الجاري لمدة 20-30 دقيقة مع إبعاد الملابس الملوثة."),listOf("البيت","المدرسة","الاستراحة","التخييم","السفر"),listOf(Link("وزارة الصحة: الإسعافات الأولية للحروق","https://www.moh.gov.sa/en/awarenessplateform/firstaid/pages/burns.aspx")),listOf())
)
